        if (!data['full-name'] || data['full-name'].trim() === '') {
            errors['full-name'] = 'Full Name is required.';
        }

        if (!data['email'] || data['email'].trim() === '') {
            errors['email'] = 'Email Address is required.';
        } else if (!isValidEmail(data['email'])) {
            errors['email'] = 'Please enter a valid email address.';
        }

        return errors;
    }

    function isValidEmail(email) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    }

    function showErrors(errors) {
        for (const [id, message] of Object.entries(errors)) {
            const input = document.getElementById(id);
            input.setAttribute('aria-invalid', 'true');

            const errorId = `${id}-error`;
            input.setAttribute('aria-describedby', input.getAttribute('aria-describedby') ? `${input.getAttribute('aria-describedby')} ${errorId}` : errorId);

            const errorElement = document.createElement('p');
            errorElement.id = errorId;
            errorElement.className = 'error-message';
            errorElement.textContent = `Error: ${message}`;

            input.parentNode.appendChild(errorElement);
        }
    }

    function clearErrors() {
        const inputs = form.querySelectorAll('input');
        inputs.forEach(input => {
            input.removeAttribute('aria-invalid');

            // Restore original aria-describedby (e.g., for phone helper)
            if (input.id === 'phone') {
                input.setAttribute('aria-describedby', 'phone-helper');
            } else {
                input.removeAttribute('aria-describedby');
            }

            const errorMsg = document.getElementById(`${input.id}-error`);
            if (errorMsg) {
                errorMsg.remove();
            }
        });
        statusMessage.textContent = '';
    }

    function focusFirstError(errors) {
        const firstErrorId = Object.keys(errors)[0];
        document.getElementById(firstErrorId).focus();
    }

    function submitForm(data) {
        // Mock submission
        statusMessage.textContent = 'Thank you! Your message has been sent.';
        statusMessage.style.color = 'var(--primary-color)';
        form.reset();
    }
});
