', direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-vanilla-js--style-dark--validation-message-absent/google/gemini-3-flash-preview__s2/script.js', full_command_text=None, hook_message=None, intention='Edit file', new_file_contents='document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('contact-form');
    const statusMessage = document.getElementById('status-message');
    const inputs = form.querySelectorAll('input');

    // Store initial aria-describedby values
    const initialDescribedBy = new Map();
    inputs.forEach(input => {
        initialDescribedBy.set(input.id, input.getAttribute('aria-describedby') || '');
    });

    form.addEventListener('submit', (event) => {
        event.preventDefault();

        clearErrors();

        const formData = new FormData(form);
        const data = Object.fromEntries(formData.entries());
        const errors = validate(data);

        if (Object.keys(errors).length > 0) {
            showErrors(errors);
            focusFirstError(errors);
        } else {
            submitForm(data);
        }
    });

    function validate(data) {
        const errors = {};

        if (!data['full-name'] || data['full-name'].trim() === '') {
            errors['full-name'] = 'Full Name is required.';
        }

        const email = data['email'] ? data['email'].trim() : '';
        if (!email) {
            errors['email'] = 'Email Address is required.';
        } else if (!isValidEmail(email)) {
            errors['email'] = 'Please enter a valid email address.';
        }

        return errors;
    }

    function isValidEmail(email) {
        // Simple but effective email regex
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    }

    function showErrors(errors) {
        for (const [id, message] of Object.entries(errors)) {
            const input = document.getElementById(id);
            input.setAttribute('aria-invalid', 'true');

            const errorId = `${id}-error`;
            const currentDescribedBy = initialDescribedBy.get(id);
            input.setAttribute('aria-describedby', currentDescribedBy ? `${currentDescribedBy} ${errorId}` : errorId);

            const errorElement = document.createElement('p');
            errorElement.id = errorId;
            errorElement.className = 'error-message';
            // Start with "Error:" for better AT context as per guidelines
            errorElement.textContent = `Error: ${message}`;

            input.parentNode.appendChild(errorElement);
        }
    }

    function clearErrors() {
        inputs.forEach(input => {
            input.removeAttribute('aria-invalid');

            const initial = initialDescribedBy.get(input.id);
            if (initial) {
                input.setAttribute('aria-describedby', initial);
            } else {
                input.removeAttribute('aria-describedby');
            }

            const errorMsg = document.getElementById(`${input.id}-error`);
            if (errorMsg) {
                errorMsg.remove();
            }
        });
        statusMessage.textContent = '';
    }

    function focusFirstError(errors) {
        const firstErrorId = Object.keys(errors)[0];
        document.getElementById(firstErrorId).focus();
    }

    function submitForm(data) {
        // Mock submission success
        statusMessage.textContent = 'Success! Your support request has been sent.';
        statusMessage.classList.remove('error');
        statusMessage.classList.add('success');
        form.reset();

        // Ensure screen reader announces success
        statusMessage.setAttribute('aria-live', 'assertive');
        setTimeout(() => {
            statusMessage.setAttribute('aria-live', 'polite');
        }, 1000);
    }
});
